   1	/**
   2	 * Document Loader — Read files from disk and prepare them for vector indexing.
   3	 *
   4	 * Supports: Markdown, JSON, TypeScript/JavaScript, and plain text files.
   5	 * Automatically chunks large documents and preserves metadata (file path, type).
   6	 *
   7	 * Provides both synchronous (`load` / `loadFile`) and asynchronous
   8	 * (`loadAsync` / `loadFileAsync`) variants.  Async methods use
   9	 * `node:fs/promises` and are recommended for large codebases to avoid
  10	 * blocking the event loop.
  11	 */
  12	
  13	import { readFileSync, readdirSync, statSync } from "node:fs";
  14	import { readdir, readFile, stat } from "node:fs/promises";
  15	import { extname, join, relative } from "node:path";
  16	import type { Dirent } from "node:fs";
  17	import type { VectorDocumentInput } from "./types.js";
  18	import { RAGError } from "./types.js";
  19	
  20	// ── Types ────────────────────────────────────────────────────────────────────
  21	
  22	export type SupportedFileType = "markdown" | "json" | "typescript" | "text";
  23	
  24	export interface DocumentLoaderOptions {
  25	  /** Root directory to scan */
  26	  rootDir: string;
  27	  /** File extensions to include (default: all supported) */
  28	  extensions?: string[];
  29	  /** Patterns to exclude (glob-like, matched against relative path) */
  30	  exclude?: string[];
  31	  /** Maximum file size in bytes (default: 1MB) */
  32	  maxFileSize?: number;
  33	  /** Chunk size in characters (default: 1500) */
  34	  chunkSize?: number;
  35	  /** Chunk overlap in characters (default: 200) */
  36	  chunkOverlap?: number;
  37	  /** Custom prefix for document IDs (default: relative file path) */
  38	  idPrefix?: string;
  39	  /**
  40	   * Optional content preprocessor.  Receives raw file content and file type;
  41	   * return the transformed text (e.g. strip frontmatter, normalize whitespace).
  42	   */
  43	  preprocess?: (content: string, fileType: SupportedFileType) => string;
  44	  /**
  45	   * Progress callback invoked after each file is loaded.
  46	   */
  47	  onFileLoaded?: (info: FileLoadedInfo) => void;
  48	}
  49	
  50	export interface FileLoadedInfo {
  51	  /** Absolute path of the loaded file */
  52	  filePath: string;
  53	  /** Relative path from rootDir */
  54	  relPath: string;
  55	  /** Detected file type */
  56	  fileType: SupportedFileType;
  57	  /** Number of chunks produced for this file */
  58	  chunkCount: number;
  59	  /** Running count of files loaded so far */
  60	  filesLoadedSoFar: number;
  61	}
  62	
  63	export interface LoadedDocument {
  64	  /** Unique document ID */
  65	  id: string;
  66	  /** Text content (or chunk) */
  67	  content: string;
  68	  /** Metadata */
  69	  metadata: Record<string, unknown>;
  70	}
  71	
  72	export interface LoadResult {
  73	  /** All loaded documents/chunks */
  74	  documents: VectorDocumentInput[];
  75	  /** Number of files scanned */
  76	  filesScanned: number;
  77	  /** Number of files loaded (passed filters) */
  78	  filesLoaded: number;
  79	  /** Number of chunks produced */
  80	  chunksProduced: number;
  81	}
  82	
  83	// ── Extension Mapping ────────────────────────────────────────────────────────
  84	
  85	const EXTENSION_MAP: Record<string, SupportedFileType> = {
  86	  ".md": "markdown",
  87	  ".mdx": "markdown",
  88	  ".json": "json",
  89	  ".jsonl": "json",
  90	  ".ts": "typescript",
  91	  ".tsx": "typescript",
  92	  ".js": "text",
  93	  ".jsx": "text",
  94	  ".mjs": "text",
  95	  ".cjs": "text",
  96	  ".txt": "text",
  97	  ".log": "text",
  98	  ".yaml": "text",
  99	  ".yml": "text",
 100	  ".toml": "text",
 101	  ".ini": "text",
 102	  ".cfg": "text",
 103	  ".env": "text",
 104	  ".sh": "text",
 105	  ".bash": "text",
 106	  ".zsh": "text",
 107	  ".py": "text",
 108	  ".go": "text",
 109	  ".rs": "text",
 110	  ".java": "text",
 111	  ".c": "text",
 112	  ".cpp": "text",
 113	  ".h": "text",
 114	  ".css": "text",
 115	  ".html": "text",
 116	  ".xml": "text",
 117	  ".sql": "text",
 118	};
