 119	  /** Delete a document by ID. Returns true if it existed. */
 120	  delete(id: string): Promise<boolean>;
 121	
 122	  /** Delete multiple documents by IDs */
 123	  deleteMany(ids: string[]): Promise<number>;
 124	
 125	  /** Check if a document exists */
